/* ---------- AND THIS LIST IS THE FLOOR, NOT THE LIBRARY § */
let FACTS_NOW = null;
let FACTS_FROM = null;

function factsBuilt_() {
  const from = (typeof DATA !== 'undefined') ? DATA : null;
  if (FACTS_NOW && FACTS_FROM === from) return FACTS_NOW;
  /* A SIXTH FIELD IS THE MINIMUM AGE TO WATCH THE CLIP, in whole years (406); blank is everyone. */
  FACTS_NOW = FEED_FACTS.map(f => ({ subject: f[0], heading: f[1], body: f[2], pic: f[3],
                                     clip: f[4] || '', age: f[5] || '' }));
  FACTS_FROM = from;
  return FACTS_NOW;
}

function factsNow_() {
  /* HEADING OR CLIP. A fact with no words is nothing; a video with no words is a video — see the note on the fifth field above. § */
  const said = sheetFacts_().filter(f => f && (f.heading || f.clip));
  return said.length ? said : factsBuilt_();
}

const sheetFacts_ = () => ((typeof DATA !== 'undefined' && DATA.facts) || []);

/* ---------- THE SHEET WINS PER LIST, NOT WHOLESALE § */
/* ---------- ONLY WHAT A `<video>` CAN PLAY, AND IN AN ORDER DEALT ONCE PER OPEN § */
const CLIP_DEAL = new Map();
function clipDealt_(list) {
  const key = f => {
    const c = String(f.clip);
    if (!CLIP_DEAL.has(c)) CLIP_DEAL.set(c, Math.random());
    return CLIP_DEAL.get(c);
  };
  return list.slice().sort((a, b) => key(a) - key(b));
}
function clipsNow_() {
  const ok = f => f && f.clip && (typeof window.clipPlayable_ !== 'function' || window.clipPlayable_(f.clip));
  const said = sheetFacts_().filter(ok);
  /* AND AN ADMIN'S OWN REELS OVER THEM, from the `media` tab (404). */
  const base = said.length ? said : factsBuilt_().filter(ok);
  const all = window.mediaReelsOver_ ? window.mediaReelsOver_(base) : base;
  /* AND ONLY WHAT THIS VIEWER IS OLD ENOUGH FOR (406). */
  return clipDealt_(window.mediaAgeOk_ ? all.filter(f => window.mediaAgeOk_(f.age)) : all);
}

/* THE COMPUTED GENERATORS lived here — times tables, factors, squares, percentages. § */


function feedShuffle() {
  const facts = factsNow_();
  const deck = facts.map((_, i) => i);
  /* ---------- IT WAS SEEDED BY THE DAY, AND THE REASON IT GAVE WAS NOT TRUE § */
  for (let i = deck.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [deck[i], deck[j]] = [deck[j], deck[i]];
  }
  FEED_PASS++;
  /* Never open on the card that just closed. Reshuffling can otherwise deal the same one twice in
     a row across the join, which is the one repeat anybody actually notices. */
  if (FEED_SEEN.length && facts[deck[0]] &&
      facts[deck[0]].heading === FEED_SEEN[FEED_SEEN.length - 1]) {
    deck.push(deck.shift());
  }
  FEED_DECK = deck;
}


function feedItem(n) {
  if (FEED_BUILT[n]) return FEED_BUILT[n];       // going back shows what you already saw

  if (!FEED_DECK.length) feedShuffle();
  /* THROUGH `factsNow_` LIKE EVERYTHING ELSE, so a filled `facts` tab reaches the widget as well as
     the column. It read `FEED_FACTS` directly, which is how the two surfaces came to disagree about
     where a fact comes from. */
  const { subject, heading, body, pic } = factsNow_()[FEED_DECK.shift()] || {};

  FEED_SEEN.push(heading);
  if (FEED_SEEN.length > 4) FEED_SEEN.shift();

  FEED_BUILT[n] = { id: 'g' + n, subject, heading, body, pic };
  return FEED_BUILT[n];
}


