function mechScope_(x) { return !x || x.kind !== 'mech' || x.mFile === 'pc' ? '' : x.mFile === 'models' ? MECH_ONE : MECH_PART; }
const mechOwn_ = (x, file, k) => (x && x.kind === 'mech' && x.mFile === file && x.mech[k]) || '';

